{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg",
        "padding": 16
      },
      "children": [
        "title_main",
        "intro_text",
        "section_title_backpacks",
        "intro_text_backpacks",
        "card_osprey",
        "card_gregory",
        "card_hyperlite",
        "section_title_quick_actions",
        "stack_quick_actions",
        "section_title_sources",
        "stack_sources"
      ]
    },
    "title_main": {
      "type": "Text",
      "props": {
        "text": "Multi-Day Hiking Backpack Recommendations",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Selecting a durable, waterproof hiking backpack for multi-day trips requires balancing comfort, capacity, and weather protection. The following recommendations offer excellent options in the 40-55 liter range, each providing robust construction, dedicated hydration sleeves, and external attachment points for trekking poles, catering to diverse weather conditions."
      },
      "children": []
    },
    "section_title_backpacks": {
      "type": "Text",
      "props": {
        "text": "Top Durable & Waterproof Backpacks (40-55L)",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text_backpacks": {
      "type": "Text",
      "props": {
        "text": "Here are three highly-regarded backpacks that meet your requirements, offering different strengths for your multi-day adventures:"
      },
      "children": []
    },
    "card_osprey": {
      "type": "Card",
      "props": {},
      "children": ["stack_osprey_content"]
    },
    "stack_osprey_content": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "stack_osprey_header",
        "text_osprey_features_label",
        "text_osprey_features",
        "text_osprey_advantages_label",
        "text_osprey_advantages",
        "text_osprey_disadvantages_label",
        "text_osprey_disadvantages",
        "button_osprey"
      ]
    },
    "stack_osprey_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": ["icon_osprey", "text_osprey_title"]
    },
    "icon_osprey": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000792_01_1_backpack.svg"
      },
      "children": []
    },
    "text_osprey_title": {
      "type": "Text",
      "props": {
        "text": "Osprey Atmos AG 50 (Men's) / Aura AG 50 (Women's) | 50L Capacity | Unparalleled Comfort",
        "variant": "h3"
      },
      "children": []
    },
    "text_osprey_features_label": {
      "type": "Text",
      "props": {
        "text": "Key Features:",
        "variant": "label"
      },
      "children": []
    },
    "text_osprey_features": {
      "type": "Text",
      "props": {
        "text": "Anti-Gravity™ (AG) suspension system, integrated FlapJacket™ for lidless use, Stow-on-the-Go™ trekking pole attachment, internal hydration sleeve, included rain cover."
      },
      "children": []
    },
    "text_osprey_advantages_label": {
      "type": "Text",
      "props": {
        "text": "Advantages:",
        "variant": "label"
      },
      "children": []
    },
    "text_osprey_advantages": {
      "type": "Text",
      "props": {
        "text": "Exceptional comfort and ventilation due to the suspended mesh backpanel and hipbelt. Good organization with multiple pockets and access points. Included rain cover provides reliable waterproofing when needed."
      },
      "children": []
    },
    "text_osprey_disadvantages_label": {
      "type": "Text",
      "props": {
        "text": "Disadvantages:",
        "variant": "label"
      },
      "children": []
    },
    "text_osprey_disadvantages": {
      "type": "Text",
      "props": {
        "text": "Not inherently waterproof; relies on the rain cover for full protection. Can be heavier than minimalist packs. The AG system can feel bulky to some users."
      },
      "children": []
    },
    "button_osprey": {
      "type": "Button",
      "props": {
        "label": "View Osprey Atmos AG 50"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.osprey.com/us/en/product/atmos-ag-50-ATMOSAG50F22.html"
          }
        }
      },
      "children": []
    },
    "card_gregory": {
      "type": "Card",
      "props": {},
      "children": ["stack_gregory_content"]
    },
    "stack_gregory_content": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "stack_gregory_header",
        "text_gregory_features_label",
        "text_gregory_features",
        "text_gregory_advantages_label",
        "text_gregory_advantages",
        "text_gregory_disadvantages_label",
        "text_gregory_disadvantages",
        "button_gregory"
      ]
    },
    "stack_gregory_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": ["icon_gregory", "text_gregory_title"]
    },
    "icon_gregory": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000792_01_1_backpack.svg"
      },
      "children": []
    },
    "text_gregory_title": {
      "type": "Text",
      "props": {
        "text": "Gregory Baltoro 65 (Men's) / Deva 60 (Women's) | 60-65L Capacity | Load-Carrying Power",
        "variant": "h3"
      },
      "children": []
    },
    "text_gregory_features_label": {
      "type": "Text",
      "props": {
        "text": "Key Features:",
        "variant": "label"
      },
      "children": []
    },
    "text_gregory_features": {
      "type": "Text",
      "props": {
        "text": "Response A3 suspension, FreeFloat A3 dynamic hipbelt, custom fit, included rain cover, hydration sleeve, multiple access points."
      },
      "children": []
    },
    "text_gregory_advantages_label": {
      "type": "Text",
      "props": {
        "text": "Advantages:",
        "variant": "label"
      },
      "children": []
    },
    "text_gregory_advantages": {
      "type": "Text",
      "props": {
        "text": "Excellent load transfer and comfort for heavy loads. Durable construction and thoughtful organization. Customizable fit for various body types."
      },
      "children": []
    },
    "text_gregory_disadvantages_label": {
      "type": "Text",
      "props": {
        "text": "Disadvantages:",
        "variant": "label"
      },
      "children": []
    },
    "text_gregory_disadvantages": {
      "type": "Text",
      "props": {
        "text": "Heavier than many other packs. Can be overkill for lighter loads or shorter trips. Not fully waterproof without the rain cover."
      },
      "children": []
    },
    "button_gregory": {
      "type": "Button",
      "props": {
        "label": "View Gregory Baltoro 65"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.gregorypacks.com/packs-bags/backpacking-packs/baltoro-65-91609XXXX.html"
          }
        }
      },
      "children": []
    },
    "card_hyperlite": {
      "type": "Card",
      "props": {},
      "children": ["stack_hyperlite_content"]
    },
    "stack_hyperlite_content": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "stack_hyperlite_header",
        "text_hyperlite_features_label",
        "text_hyperlite_features",
        "text_hyperlite_advantages_label",
        "text_hyperlite_advantages",
        "text_hyperlite_disadvantages_label",
        "text_hyperlite_disadvantages",
        "button_hyperlite"
      ]
    },
    "stack_hyperlite_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": ["icon_hyperlite", "text_hyperlite_title"]
    },
    "icon_hyperlite": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000792_01_1_backpack.svg"
      },
      "children": []
    },
    "text_hyperlite_title": {
      "type": "Text",
      "props": {
        "text": "Hyperlite Mountain Gear 3400 Southwest | 55L Capacity | Ultralight & Waterproof",
        "variant": "h3"
      },
      "children": []
    },
    "text_hyperlite_features_label": {
      "type": "Text",
      "props": {
        "text": "Key Features:",
        "variant": "label"
      },
      "children": []
    },
    "text_hyperlite_features": {
      "type": "Text",
      "props": {
        "text": "Made from Dyneema® Composite Fabrics (DCF), roll-top closure, external pockets for quick access, minimalist design, internal hydration sleeve."
      },
      "children": []
    },
    "text_hyperlite_advantages_label": {
      "type": "Text",
      "props": {
        "text": "Advantages:",
        "variant": "label"
      },
      "children": []
    },
    "text_hyperlite_advantages": {
      "type": "Text",
      "props": {
        "text": "Extremely lightweight and highly waterproof (DCF material). Durable and abrasion-resistant for its weight. Simple, efficient design for ultralight backpacking."
      },
      "children": []
    },
    "text_hyperlite_disadvantages_label": {
      "type": "Text",
      "props": {
        "text": "Disadvantages:",
        "variant": "label"
      },
      "children": []
    },
    "text_hyperlite_disadvantages": {
      "type": "Text",
      "props": {
        "text": "Higher price point. Less comfortable with very heavy loads compared to traditional framed packs. Minimal internal organization."
      },
      "children": []
    },
    "button_hyperlite": {
      "type": "Button",
      "props": {
        "label": "View HMG 3400 Southwest"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.hyperlitemountaingear.com/products/3400-southwest"
          }
        }
      },
      "children": []
    },
    "section_title_quick_actions": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "stack_quick_actions": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "wrap": "wrap"
      },
      "children": ["button_compare_packs", "button_find_deals"]
    },
    "button_compare_packs": {
      "type": "Button",
      "props": {
        "label": "Compare Backpacks"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.rei.com/learn/expert-advice/backpacks-comparison.html"
          }
        }
      },
      "children": []
    },
    "button_find_deals": {
      "type": "Button",
      "props": {
        "label": "Find Deals on Hiking Gear"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.backcountry.com/hiking-backpacks"
          }
        }
      },
      "children": []
    },
    "section_title_sources": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "stack_sources": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": ["button_source_osprey", "button_source_gregory", "button_source_hyperlite"]
    },
    "button_source_osprey": {
      "type": "Button",
      "props": {
        "label": "Osprey Packs Official Site"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.osprey.com"
          }
        }
      },
      "children": []
    },
    "button_source_gregory": {
      "type": "Button",
      "props": {
        "label": "Gregory Packs Official Site"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.gregorypacks.com"
          }
        }
      },
      "children": []
    },
    "button_source_hyperlite": {
      "type": "Button",
      "props": {
        "label": "Hyperlite Mountain Gear Official Site"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.hyperlitemountaingear.com"
          }
        }
      },
      "children": []
    }
  }
}
